package za.ac.univen.clone;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import org.jsoup.Jsoup;
import org.springframework.stereotype.Service;

@Service
class MailService {
 static final String ICT="ICTSupport@univen.ac.za", GMAIL="https://gmail.googleapis.com/gmail/v1/users/me", GRAPH="https://graph.microsoft.com/v1.0/me";
 private final AccountService accounts;private final ProviderHttp http;private final Object[] locks=new Object[64];
 MailService(AccountService accounts,ProviderHttp http){this.accounts=accounts;this.http=http;Arrays.setAll(locks,i->new Object());}
 private Object lock(Map<String,Object> account){return locks[Math.floorMod(Data.text(account,"id").hashCode(),locks.length)];}
 private Map<String,Object> reload(Map<String,Object> account){return accounts.repository.get(Data.text(account,"id"));}
 private Map<String,Object> request(Map<String,Object> account,String provider,String path,String method,Object body){String base=provider.equals("google")?GMAIL:GRAPH;String url=path.startsWith("https://")?path:base+path;if(!url.startsWith(base+"/"))throw new ApiProblem(502,"PROVIDER_ERROR","Unexpected mailbox destination.");return http.request(url,method,accounts.token(account,provider),body);}
 private List<Map<String,Object>> pages(Map<String,Object> account,String provider,String path){var result=new ArrayList<Map<String,Object>>();var seen=new HashSet<String>();String next=path;while(!next.isBlank()){if(seen.size()>=100||!seen.add(next))throw new ApiProblem(502,"PROVIDER_ERROR","Support history could not be loaded completely. Please retry.");var page=request(account,provider,next,"GET",null);result.addAll(Data.list(page.get(provider.equals("google")?"messages":"value")));if(provider.equals("google")){String token=Data.text(page,"nextPageToken");next=token.isBlank()?"":path+"&pageToken="+ProviderHttp.encode(token);}else next=Data.text(page,"@odata.nextLink");}return result;}
 private static void requireText(Map<String,Object> input,String key,int limit){Object value=input.get(key);if(!(value instanceof String text)||text.isBlank()||text.length()>limit)throw new ApiProblem(400,"INVALID_INPUT","Enter a valid "+key+".");}
 private List<Map<String,Object>> attachments(Object value){if(value==null)return List.of();if(!(value instanceof List<?> items)||items.size()>10)throw new ApiProblem(400,"INVALID_INPUT","Use up to ten attachments.");var result=new ArrayList<Map<String,Object>>();int total=0;for(Object item:items){var file=Data.obj(item);requireText(file,"name",200);requireText(file,"contentBytes",3*1024*1024);String encoded=Data.text(file,"contentBytes");try{if(!encoded.matches("[A-Za-z0-9+/]*={0,2}"))throw new IllegalArgumentException();total+=Base64.getDecoder().decode(encoded).length;}catch(Exception e){throw new ApiProblem(400,"INVALID_INPUT","Invalid attachment.");}if(total>2*1024*1024)throw new ApiProblem(400,"INVALID_INPUT","Keep attachments under 2 MB in total.");result.add(Data.map("name",file.get("name"),"contentType","application/octet-stream","contentBytes",encoded));}return result;}
 Map<String,Object> send(Map<String,Object> authenticated,Map<String,Object> input){synchronized(lock(authenticated)){var account=reload(authenticated);String provider=Data.text(input,"provider");var identity=Data.list(account.get("identities")).stream().filter(i->provider.equals(i.get("provider"))).findFirst().orElseThrow(()->new ApiProblem(400,"NOT_CONNECTED","Connect the selected email account first."));var proposed=Data.obj(input.get("ticket"));if(!Data.text(proposed,"id").matches("APP-\\d{4}-[0-9a-f-]{36}"))throw new ApiProblem(400,"INVALID_INPUT","Invalid app reference.");for(var entry:Map.of("title",160,"description",4000,"category",100,"subcategory",200,"contactNumber",100).entrySet())requireText(proposed,entry.getKey(),entry.getValue());var files=attachments(input.get("attachments"));String id=Data.text(proposed,"id");var call=Data.list(account.get("calls")).stream().filter(c->id.equals(Data.obj(c.get("ticket")).get("id"))).findFirst().orElse(null);
  if(call==null){String now=Instant.now().toString();var ticket=Data.map("id",id,"studentNumber",account.getOrDefault("studentNumber",account.get("id")),"studentName",account.get("name"),"email",identity.get("email"),"contactNumber",proposed.get("contactNumber"),"category",proposed.get("category"),"subcategory",proposed.get("subcategory"),"title",proposed.get("title"),"description",proposed.get("description"),"priority",Set.of("Low","Medium","High","Urgent").contains(Data.text(proposed,"priority"))?proposed.get("priority"):"Medium","status","Submitted","createdAt",now,"updatedAt",now,"deviceInfo","","attachments",files.stream().map(f->Data.map("name",f.get("name"),"type",f.get("contentType"),"size",(Base64.getDecoder().decode(Data.text(f,"contentBytes")).length+1023)/1024+" KB")).toList(),"comments",new ArrayList<>(List.of(Data.map("id",UUID.randomUUID().toString(),"sender","student","senderName",account.get("name"),"text",proposed.get("description"),"timestamp",now))));call=Data.map("ticket",ticket,"provider",provider,"delivery","pending","replies",Data.map());Data.list(account.get("calls")).add(call);accounts.repository.save(account);
  }else if(!provider.equals(call.get("provider")))throw new ApiProblem(409,"CONFLICT","Retry this request using its original email provider.");
  var ticket=Data.obj(call.get("ticket"));if("accepted".equals(call.get("delivery")))return ticket;
  String text=Data.text(ticket,"description")+"\n\nApp reference: "+id+"\nStudent: "+account.get("name")+" ("+ticket.get("studentNumber")+")\nCallback: "+ticket.get("contactNumber")+"\nCategory: "+ticket.get("category")+" / "+ticket.get("subcategory")+"\nPriority: "+ticket.get("priority");
  deliver(account,call,call,id,text,files,false);return ticket;
 }}
 private void deliver(Map<String,Object> account,Map<String,Object> call,Map<String,Object> operation,String id,String text,List<Map<String,Object>> files,boolean reply){String provider=Data.text(call,"provider");var ticket=Data.obj(call.get("ticket"));accounts.token(account,provider);
  if("accepted".equals(operation.get("delivery")))return;
  if(provider.equals("google")){
   if("uncertain".equals(operation.get("delivery"))){var found=findSent(account,id);if(found==null)throw new ApiProblem(409,"DELIVERY_UNCERTAIN","Sending is not confirmed. Refresh or check this app reference in Gmail before creating another call.");operation.put("messageId",found.get("id"));operation.put("threadId",found.get("threadId"));operation.put("delivery","accepted");accounts.repository.save(account);return;}
   var body=Data.map("raw",mime(ticket,text,id,files,reply));if(reply&&!Data.text(call,"threadId").isBlank())body.put("threadId",call.get("threadId"));operation.put("delivery","uncertain");accounts.repository.save(account);var sent=request(account,provider,"/messages/send","POST",body);operation.put("messageId",sent.get("id"));operation.put("threadId",sent.get("threadId"));operation.put("delivery","accepted");accounts.repository.save(account);
  }else{
   if(Data.text(operation,"draftId").isBlank()){
    var body=Data.map("subject",(reply?"Re: ":"")+"["+ticket.get("id")+"] "+ticket.get("title"),"body",Data.map("contentType","Text","content",text),"toRecipients",List.of(Data.map("emailAddress",Data.map("address",ICT))),"internetMessageHeaders",List.of(Data.map("name","x-univen-app-reference","value",ticket.get("id"))),"singleValueExtendedProperties",List.of(Data.map("id","String {61440681-0a55-47d1-a5c4-c114e151a1d1} Name AppSource","value","univen-student-support-v1"),Data.map("id","String {61440681-0a55-47d1-a5c4-c114e151a1d1} Name SupportRecord","value",Data.json(Data.map("version",1,"kind",reply?"reply":"call","ticket",ticket,"text",text)))),"attachments",files.stream().map(file->{var f=new LinkedHashMap<>(file);f.put("@odata.type","#microsoft.graph.fileAttachment");return f;}).toList());
    var draft=request(account,provider,"/messages","POST",body);operation.put("draftId",draft.get("id"));operation.put("conversationId",draft.get("conversationId"));accounts.repository.save(account);
   }
   String draft=Data.text(operation,"draftId");if("uncertain".equals(operation.get("delivery"))){var message=request(account,provider,"/messages/"+ProviderHttp.encode(draft)+"?$select=id,isDraft,conversationId","GET",null);if(!Boolean.FALSE.equals(message.get("isDraft")))throw new ApiProblem(409,"DELIVERY_UNCERTAIN","Sending is not confirmed. Check this app reference in Outlook before creating another call.");}else{operation.put("delivery","uncertain");accounts.repository.save(account);request(account,provider,"/messages/"+ProviderHttp.encode(draft)+"/send","POST",null);}operation.put("delivery","accepted");accounts.repository.save(account);
  }
 }
 static String mime(Map<String,Object> ticket,String text,String operation,List<Map<String,Object>> files,boolean reply){String boundary="support-"+UUID.randomUUID();String subject=(reply?"Re: ":"")+(Data.text(ticket,"externalTicketId").isBlank()?"":"["+ticket.get("externalTicketId")+"] ")+"["+ticket.get("id")+"] "+ticket.get("title");StringBuilder out=new StringBuilder("To: "+ICT+"\r\nSubject: "+encodedHeader(subject)+"\r\nMessage-ID: <app-"+operation+"@student-support.invalid>\r\nX-Univen-App-Reference: "+ticket.get("id")+"\r\nMIME-Version: 1.0\r\n");if(reply)out.append("In-Reply-To: <app-").append(ticket.get("id")).append("@student-support.invalid>\r\nReferences: <app-").append(ticket.get("id")).append("@student-support.invalid>\r\n");out.append("Content-Type: multipart/mixed; boundary=\"").append(boundary).append("\"\r\n\r\n--").append(boundary).append("\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n").append(Base64.getMimeEncoder().encodeToString(text.getBytes(StandardCharsets.UTF_8))).append("\r\n");for(var file:files)out.append("--").append(boundary).append("\r\nContent-Type: application/octet-stream\r\nContent-Disposition: attachment; filename=\"").append(encodedHeader(Data.text(file,"name"))).append("\"\r\nContent-Transfer-Encoding: base64\r\n\r\n").append(Base64.getMimeEncoder().encodeToString(Base64.getDecoder().decode(Data.text(file,"contentBytes")))).append("\r\n");out.append("--").append(boundary).append("--\r\n");return Base64.getUrlEncoder().withoutPadding().encodeToString(out.toString().getBytes(StandardCharsets.UTF_8));}
 static String encodedHeader(String value){var pieces=new ArrayList<String>();var chunk=new StringBuilder();for(int point:value.codePoints().toArray()){String next=new String(Character.toChars(point));if((chunk.toString()+next).getBytes(StandardCharsets.UTF_8).length>39){pieces.add("=?UTF-8?B?"+Base64.getEncoder().encodeToString(chunk.toString().getBytes(StandardCharsets.UTF_8))+"?=");chunk.setLength(0);}chunk.append(next);}if(!chunk.isEmpty())pieces.add("=?UTF-8?B?"+Base64.getEncoder().encodeToString(chunk.toString().getBytes(StandardCharsets.UTF_8))+"?=");return String.join("\r\n ",pieces);}
 private Map<String,Object> findSent(Map<String,Object> account,String id){for(String query:List.of("in:sent rfc822msgid:app-"+id+"@student-support.invalid","in:anywhere \""+id+"\"","in:sent subject:\"["+id+"]\"")){var page=request(account,"google","/messages?q="+ProviderHttp.encode(query)+"&maxResults=10","GET",null);var found=Data.list(page.get("messages")).stream().findFirst().orElse(null);if(found!=null)return found;}return null;}
 Map<String,Object> reply(Map<String,Object> authenticated,Map<String,Object> input){synchronized(lock(authenticated)){var account=reload(authenticated);requireText(input,"text",4000);String id=Data.text(input,"operationId");if(!id.matches("[0-9a-f-]{36}"))throw new ApiProblem(400,"INVALID_INPUT","Invalid reply reference.");var call=Data.list(account.get("calls")).stream().filter(c->Data.text(input,"ticketId").equals(Data.obj(c.get("ticket")).get("id"))&&"accepted".equals(c.get("delivery"))).findFirst().orElseThrow(()->new ApiProblem(404,"NOT_FOUND","Support request not found in your app account."));var ticket=Data.obj(call.get("ticket"));var replies=Data.obj(call.get("replies"));Map<String,Object> operation=Data.obj(replies.get(id));if(operation.isEmpty()){operation=Data.map("text",input.get("text"),"delivery","pending");replies.put(id,operation);}if(!operation.get("text").equals(input.get("text")))throw new ApiProblem(409,"CONFLICT","Keep the same text when retrying this reply.");if(!"accepted".equals(operation.get("delivery")))deliver(account,call,operation,id,Data.text(input,"text"),List.of(),true);if(Data.list(ticket.get("comments")).stream().noneMatch(c->id.equals(c.get("id")))){String now=Instant.now().toString();Data.list(ticket.get("comments")).add(Data.map("id",id,"sender","student","senderName",account.get("name"),"text",input.get("text"),"timestamp",now));ticket.put("updatedAt",now);accounts.repository.save(account);}return ticket;}}
 Map<String,Object> refresh(Map<String,Object> authenticated){synchronized(lock(authenticated)){var account=reload(authenticated);var warnings=new LinkedHashSet<String>();for(var call:Data.list(account.get("calls"))){try{String provider=Data.text(call,"provider");var ticket=Data.obj(call.get("ticket"));if(!"accepted".equals(call.get("delivery"))){if("uncertain".equals(call.get("delivery")))deliver(account,call,call,Data.text(ticket,"id"),"",List.of(),false);else continue;}if(provider.equals("google"))gmailReplies(account,call);else outlookReplies(account,call);}catch(ApiProblem error){warnings.add(error.getMessage());}}accounts.repository.save(account);var tickets=Data.list(account.get("calls")).stream().filter(c->"accepted".equals(c.get("delivery"))).map(c->Data.obj(c.get("ticket"))).sorted((a,b)->Data.text(b,"createdAt").compareTo(Data.text(a,"createdAt"))).toList();return Data.map("tickets",tickets,"warnings",warnings);}}
 static String header(Map<String,Object> payload,String name){return Data.list(payload.get("headers")).stream().filter(h->name.equalsIgnoreCase(Data.text(h,"name"))).map(h->Data.text(h,"value")).findFirst().orElse("");}
 static String extract(Map<String,Object> part,String mime){if(mime.equals(part.get("mimeType"))&&!Data.text(Data.obj(part.get("body")),"data").isBlank()){try{return new String(Base64.getUrlDecoder().decode(Data.text(Data.obj(part.get("body")),"data")),StandardCharsets.UTF_8);}catch(Exception e){return "";}}return String.join("\n",Data.list(part.get("parts")).stream().map(p->extract(p,mime)).filter(s->!s.isBlank()).toList());}
 private void gmailReplies(Map<String,Object> account,Map<String,Object> call){var ticket=Data.obj(call.get("ticket"));String id=Data.text(ticket,"id"),external=Data.text(ticket,"externalTicketId");String query="in:anywhere (\""+id+"\" OR subject:\""+id+"\")";var entries=new LinkedHashMap<String,Map<String,Object>>();String threadId=Data.text(call,"threadId");if(!threadId.isBlank()){var thread=request(account,"google","/threads/"+ProviderHttp.encode(threadId)+"?format=full","GET",null);for(var entry:Data.list(thread.get("messages")))entries.put(Data.text(entry,"id"),entry);}for(var entry:pages(account,"google","/messages?q="+ProviderHttp.encode(query)+"&maxResults=100"))entries.putIfAbsent(Data.text(entry,"id"),entry);var messages=new ArrayList<Map<String,Object>>();for(var entry:entries.values()){var message=Data.obj(entry.get("payload")).isEmpty()?request(account,"google","/messages/"+ProviderHttp.encode(Data.text(entry,"id"))+"?format=full","GET",null):entry;var payload=Data.obj(message.get("payload"));String from=header(payload,"from"),address=Data.match("<([^>]+)>",from);if(address.isEmpty())address=from.trim();if(!trusted(address)||address.equalsIgnoreCase(Data.text(ticket,"email")))continue;String subject=header(payload,"subject"),marker=header(payload,"x-univen-app-reference"),text=extract(payload,"text/plain");if(text.isBlank())text=Jsoup.parse(extract(payload,"text/html")).text();boolean linked=signatureMatches(id,"",marker)||signatureMatches(id,subject,text)||(!external.isBlank()&&signatureMatches(external,subject,text))||Data.text(entry,"threadId").equals(threadId);if(!linked||text.isBlank())continue;messages.add(Data.map("id","google-"+entry.get("id"),"subject",subject,"text",text,"sender",from.replaceAll("<[^>]+>","").replace("\"","").trim(),"timestamp",Instant.ofEpochMilli((long)Data.number(Data.text(message,"internalDate"))).toString()));}messages.sort(Comparator.comparing(m->Data.text(m,"timestamp")));for(var message:messages)applyReply(ticket,message);}
 static boolean signatureMatches(String reference,String subject,String text){if(reference.isBlank())return false;String value=(subject+"\n"+text).replaceAll("\\s+"," ").toLowerCase(Locale.ROOT);return value.contains(reference.replaceAll("\\s+"," ").toLowerCase(Locale.ROOT));}
 private void outlookReplies(Map<String,Object> account,Map<String,Object> call){var ticket=Data.obj(call.get("ticket"));String conversation=Data.text(call,"conversationId");if(conversation.isBlank()){var root=request(account,"microsoft","/messages/"+ProviderHttp.encode(Data.text(call,"draftId"))+"?$select=id,conversationId,isDraft","GET",null);conversation=Data.text(root,"conversationId");call.put("conversationId",conversation);}if(conversation.isBlank())return;String filter="conversationId eq '"+conversation.replace("'","''")+"'";var messages=pages(account,"microsoft","/messages?$filter="+ProviderHttp.encode(filter)+"&$select=id,conversationId,isDraft,subject,from,body,receivedDateTime&$top=50");messages.sort(Comparator.comparing(m->Data.text(m,"receivedDateTime")));for(var message:messages){var from=Data.obj(Data.obj(message.get("from")).get("emailAddress"));if(Boolean.TRUE.equals(message.get("isDraft"))||!conversation.equals(message.get("conversationId"))||!trusted(Data.text(from,"address")))continue;var body=Data.obj(message.get("body"));String text=Data.text(body,"content");if("html".equalsIgnoreCase(Data.text(body,"contentType")))text=Jsoup.parse(text).text();applyReply(ticket,Data.map("id","microsoft-"+message.get("id"),"subject",message.get("subject"),"text",text,"sender",from.getOrDefault("name","ICT Support"),"timestamp",message.get("receivedDateTime")));}}
 static boolean trusted(String address){String value=address.trim().toLowerCase();return value.equals(ICT.toLowerCase())||value.matches("[^\\s<>@]+@univen\\.ac\\.za");}
 static void applyReply(Map<String,Object> ticket,Map<String,Object> message){String id=Data.text(message,"id");if(Data.list(ticket.get("comments")).stream().anyMatch(c->id.equals(c.get("id"))))return;String text=Data.text(message,"text"),combined=Data.text(message,"subject")+"\n"+text;String external=Data.match("(?:Incident|Ticket|Call|Case|Request|Ref(?:erence)?)\\s*(?:Number|No\\.?|#|ID)?\\s*[:#]\\s*([A-Za-z0-9,_/-]{3,25})",combined);if(external.isBlank())external=Data.match("\\b((?:INC|REQ|TKT|CAS|CALL|HD|SD|IT)[-_]?[0-9]{4,10})\\b",combined);if(!external.isBlank())ticket.put("externalTicketId",external);String raw=Data.match("(?:Status|State)\\s*[:\\-]\\s*([^\\r\\n.]+)",combined).toLowerCase();String status=raw.contains("in progress")||raw.contains("investigat")?"In Progress":raw.contains("wait")||raw.contains("pending")?"Waiting for Student":raw.contains("resolv")||raw.contains("complet")?"Resolved":raw.contains("closed")?"Closed":raw.contains("escalat")?"Escalated":raw.contains("assign")?"Assigned":raw.contains("new")||raw.contains("received")?"Received":"";if(!status.isBlank()&&(!Set.of("Resolved","Closed").contains(Data.text(ticket,"status"))||Set.of("Resolved","Closed").contains(status)))ticket.put("status",status);String assigned=Data.match("(?:Assigned to|Technician|Consultant)\\s*[:\\-]\\s*([^\\r\\n]+)",combined);if(!assigned.isBlank()&&!assigned.equalsIgnoreCase("none"))ticket.put("assignedTo",assigned);String department=Data.match("(?:Admin group|Department|Support group)\\s*[:\\-]\\s*([^\\r\\n]+)",combined);if(!department.isBlank())ticket.put("assignedDepartment",department);String solution=Data.match("(?:Solution|Resolution)\\s*[:\\-]\\s*([^\\r\\n]+)",combined);if(!solution.isBlank())ticket.put("solution",solution);String clean=text.split("(?im)^On .+wrote:|^From:|^-----Original Message-----",2)[0].replaceAll("(?is)<script[^>]*>.*?</script>","").trim();if(clean.length()>16000)clean=clean.substring(0,16000);String timestamp=Data.text(message,"timestamp");if(timestamp.isBlank())timestamp=Instant.now().toString();Data.list(ticket.get("comments")).add(Data.map("id",id,"sender","technician","senderName",Data.text(message,"sender").isBlank()?"ICT Support":message.get("sender"),"text",clean,"timestamp",timestamp));Data.list(ticket.get("comments")).sort(Comparator.comparing(c->Data.text(c,"timestamp")));ticket.put("updatedAt",Data.list(ticket.get("comments")).getLast().get("timestamp"));}
}
